# lending-desk

The lending desk service of the city library's branches: checkouts, returns, renewals, holds, fees,
notices to members, and the self-check machines.

Plain Node.js ES modules, no dependencies. Node.js 22 or later.

```sh
npm test    # runs every test in test/
npm start   # serves the API on port 8080, with demo data
```
import { outstandingBalance } from '../../fees/balance.js';
import { formatCents } from '../../helpers/money.js';
import { displayName } from '../../members/accounts.js';
import { ok } from '../respond.js';

/** The routes about a member's account. */
export function memberRoutes(store) {
  return [
    {
      method: 'GET',
      path: '/members/:id/summary',
      handle: ({ params }) => {
        const member = store.getMember(params.id);
        const balanceCents = outstandingBalance(store, member.id);
        return ok({
          id: member.id,
          name: displayName(member),
          loanCount: store.listOpenLoans(member.id).length,
          balanceCents,
          balance: formatCents(balanceCents),
        });
      },
    },
  ];
}
/** Returns the loans not returned whose due date is before `today`, the longest overdue first. */
export function listOverdueLoans(store, today) {
  return store
    .listAllLoans()
    .filter((loan) => loan.returnedOn === null && loan.dueOn < today)
    .sort((first, second) => first.dueOn.localeCompare(second.dueOn));
}
/** Returns the member who holds this library card number, or undefined when nobody does. */
export function findMemberByCard(store, cardNumber) {
  return store.listMembers().find((member) => member.cardNumber === cardNumber);
}

/** Returns the name to greet a member by: their preferred name when they gave one. */
export function displayName(member) {
  return member.preferredName ?? member.name;
}
import { LOAN_RULES } from '../config/defaults.js';
import { addDays, nextOpenDay } from '../helpers/dates.js';

/**
 * Returns the day a loan of an item of this format, lent or renewed on `checkedOutOn`, falls due:
 * the end of the format's loan period, or the branch's next open day after it.
 */
export function computeDueDate({ checkedOutOn, format, branch }) {
  return nextOpenDay(branch, addDays(checkedOutOn, LOAN_RULES[format].loanDays));
}
