import { isValidBarcode, normaliseBarcode } from '../../catalog/barcodes.js';
import { checkOutItem } from '../../circulation/checkout.js';
import { renewLoan } from '../../circulation/renewals.js';
import { returnItem } from '../../circulation/returns.js';
import { fail, ok } from '../respond.js';

/** The routes of checkouts, returns and renewals. */
export function loanRoutes(store) {
  return [
    {
      method: 'POST',
      path: '/checkouts',
      handle: ({ body, today }) => {
        if (!isValidBarcode(normaliseBarcode(body.barcode)))
          return fail(400, 'invalid-barcode', 'Not a barcode');
        const result = checkOutItem(store, { barcode: body.barcode, memberId: body.memberId, today });
        return result.ok
          ? ok({ loan: result.loan }, 201)
          : fail(409, result.reason, 'The item cannot be lent');
      },
    },
    {
      method: 'POST',
      path: '/returns',
      handle: ({ body, today }) => {
        const result = returnItem(store, { barcode: body.barcode, today });
        return result.ok
          ? ok({ loan: result.loan, feeCents: result.feeCents })
          : fail(409, result.reason, 'No loan');
      },
    },
    {
      method: 'POST',
      path: '/loans/:id/renew',
      handle: ({ params, today }) => {
        const result = renewLoan(store, { loanId: params.id, today });
        return result.ok ? ok({ loan: result.loan }) : fail(409, result.reason, 'The loan cannot be renewed');
      },
    },
  ];
}
import { matchPath } from './match-path.js';
import { fail } from './respond.js';
import { catalogRoutes } from './routes/catalog.js';
import { holdRoutes } from './routes/holds.js';
import { loanRoutes } from './routes/loans.js';
import { memberRoutes } from './routes/members.js';

/**
 * Builds the lending desk API over a store. Its handle(request) takes { method, path, query,
 * body, today } and returns { status, body }.
 */
export function createApp(store) {
  const routes = [
    ...loanRoutes(store),
    ...holdRoutes(store),
    ...memberRoutes(store),
    ...catalogRoutes(store),
  ];
  return {
    handle(request) {
      for (const route of routes) {
        if (route.method !== request.method) continue;
        const params = matchPath(route.path, request.path);
        if (params !== null) return route.handle({ ...request, params });
      }
      return fail(404, 'route-not-found', `No route for ${request.method} ${request.path}`);
    },
  };
}
// Days are calendar dates written as YYYY-MM-DD, read as UTC so that the server's time zone never
// shifts them.
const DAY_MS = 86_400_000;

function toTime(isoDate) {
  return Date.parse(`${isoDate}T00:00:00Z`);
}

/** Returns the calendar date `days` days after `isoDate`, or before it when `days` is negative. */
export function addDays(isoDate, days) {
  return new Date(toTime(isoDate) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Returns how many days `later` is after `earlier`, negative when it is before. */
export function daysBetween(earlier, later) {
  return Math.round((toTime(later) - toTime(earlier)) / DAY_MS);
}

/** Returns the day of the week of a calendar date, 0 for Sunday to 6 for Saturday. */
export function weekdayOf(isoDate) {
  return new Date(toTime(isoDate)).getUTCDay();
}

/** Tells whether a branch is open on a calendar date. */
export function isOpenOn(branch, isoDate) {
  return !branch.closedWeekdays.includes(weekdayOf(isoDate));
}

/** Returns the first date on or after `isoDate` on which the branch is open. */
export function nextOpenDay(branch, isoDate) {
  let day = isoDate;
  while (!isOpenOn(branch, day)) day = addDays(day, 1);
  return day;
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { createApp } from '../lib/server/app.js';
import { ADA, BOOK, DVD, sampleLoan, sampleStore, TODAY } from './sample-library.js';

function request(method, path, { body = null, query = {} } = {}) {
  return { method, path, query, body, today: TODAY };
}

test('POST /checkouts lends an item', () => {
  const app = createApp(sampleStore());
  const response = app.handle(
    request('POST', '/checkouts', { body: { barcode: BOOK.barcode, memberId: ADA.id } }),
  );
  assert.equal(response.status, 201);
  assert.equal(response.body.loan.dueOn, '2026-12-17');
});

test('POST /checkouts refuses a barcode with a wrong check digit', () => {
  const app = createApp(sampleStore());
  const response = app.handle(
    request('POST', '/checkouts', { body: { barcode: '31234000000017', memberId: ADA.id } }),
  );
  assert.equal(response.status, 400);
  assert.equal(response.body.error.code, 'invalid-barcode');
});

test('POST /loans/:id/renew answers a refusal with its reason as the error code', () => {
  const loan = sampleLoan({
    id: 'loan_1',
    item: DVD,
    member: ADA,
    checkedOutOn: '2026-11-01',
    dueOn: '2026-11-08',
  });
  const app = createApp(sampleStore({ loans: [loan] }));
  const response = app.handle(request('POST', '/loans/loan_1/renew'));
  assert.equal(response.status, 409);
  assert.equal(response.body.error.code, 'overdue');
});

test('GET /members/:id/summary gives the loans and the balance of a member', () => {
  const loan = sampleLoan({
    id: 'loan_1',
    item: BOOK,
    member: ADA,
    checkedOutOn: '2026-11-20',
    dueOn: '2026-12-11',
  });
  const fees = [
    { id: 'fee_1', memberId: ADA.id, loanId: 'loan_0', amountCents: 250, paid: false, waivedReason: null },
  ];
  const app = createApp(sampleStore({ loans: [loan], fees }));
  const response = app.handle(request('GET', `/members/${ADA.id}/summary`));
  assert.equal(response.status, 200);
  assert.equal(response.body.loanCount, 1);
  assert.equal(response.body.balance, '$2.50');
});

test('GET /catalog searches the catalog', () => {
  const app = createApp(sampleStore());
  const response = app.handle(request('GET', '/catalog', { query: { q: 'spirited' } }));
  assert.deepEqual(
    response.body.items.map((item) => item.id),
    [DVD.id],
  );
});

test('an unknown route answers 404', () => {
  const response = createApp(sampleStore()).handle(request('GET', '/nowhere'));
  assert.equal(response.status, 404);
  assert.equal(response.body.error.code, 'route-not-found');
});
