/** Tells whether a loan is overdue: not returned, and its due date is before `today`. */
export function isOverdue(loan, today) {
  return loan.returnedOn === null && loan.dueOn < today;
}

/** Returns the loans not returned whose due date is before `today`, the longest overdue first. */
export function listOverdueLoans(store, today) {
  return store
    .listAllLoans()
    .filter((loan) => isOverdue(loan, today))
    .sort((first, second) => first.dueOn.localeCompare(second.dueOn));
}
EOF
